    <h2 id="studio-make-h" class="label">Make</h2>
    <div class="studio-pick"><div class="studio-types" role="radiogroup" aria-label="What to make">${types.map((t) => typeCard(t, t.name === chosen?.name))}</div>${typeDetail(chosen)}</div>
