      ${audio === "music" ? html`<label for="studio-lyrics">Lyrics (optional)</label><textarea id="studio-lyrics" name="lyrics" rows="3" maxlength="3000" placeholder="Leave empty for an instrumental">${lyrics}</textarea>` : ""}
